tests:
test('reverses a word', () => { assert.equal(reverseString('hello'), 'olleh'); });
test('reverses words separated by spaces', () => { assert.equal(reverseString('a b c'), 'c b a'); });
test('empty string stays empty', () => { assert.equal(reverseString(''), ''); });
test('single character is unchanged', () => { assert.equal(reverseString('x'), 'x'); });

referenceSolution:
function reverseString(text) {
  let result = '';
  for (const character of text) {
    result = character + result;
  }
  return result;
}
